<?php elseif($tab==='analytics'&&has_permission('bloodbank.analytics',$me)):?><section class="bb570-admin-grid"><div class="panel span2"><div class="panel-head"><div><span>14-DAY ACTIVITY</span><h3>Portal engagement</h3></div></div><div class="activity-chart"><?php foreach($activity as $x):?><div title="<?=e($x['d'])?> · <?=(int)$x['n']?>"><i style="height:<?=max(5,round(((int)$x['n']/$maxAct)*100))?>%"></i><span><?=e(date('d M',strtotime($x['d'])))?></span></div><?php endforeach;?></div></div><div class="panel"><div class="panel-head"><div><span>PRIVACY</span><h3>Analytics design</h3></div></div><p class="muted">Public activity uses a one-way daily visitor hash. Raw visitor IP addresses are not stored in the Blood Bank analytics table.</p></div><div class="panel span3"><div class="panel-head"><div><span>INVENTORY HEALTH</span><h3>Current group availability</h3></div></div><div class="stock-matrix wide"><?php foreach($invSummary as $g=>$n):?><div class="<?=$n<2?'low':''?>"><b><?=e($g)?></b><strong><?=$n?></strong><span>units</span></div><?php endforeach;?></div></div></section>
<?php elseif($tab==='staff'):?><section class="admin-split"><div class="panel"><div class="panel-head"><div><span>ROLE-SCOPED ACCESS</span><h3>Blood Bank users</h3></div></div><div class="privacy-strip">These assignments can give a normal ShahkotPK user Admin access limited to Blood Bank permissions only. Bank-specific assignments restrict that staff record to one blood bank.</div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Blood bank</th><th>Permissions</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($staff as $s):$pp=json_decode((string)$s['permissions_json'],true)?:[];?><tr><td><b><?=e($s['user_name'])?></b><small><?=e($s['email'])?></small></td><td><?=e($s['access_role'])?></td><td><?=e($s['bank_name']?:'All tenant blood banks')?></td><td><small><?=e(implode(', ',$pp))?></small></td><td><?=$s['status']?'Active':'Disabled'?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_staff"><input type="hidden" name="staff_id" value="<?=(int)$s['id']?>"><button><?=$s['status']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div><aside class="panel form-panel"><h3>Assign Blood Bank user</h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign_staff"><label>User<select name="user_id" required><option value="">Choose user</option><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>"><?=e($u['name'].' · '.$u['email'])?></option><?php endforeach;?></select></label><label>Access role<select name="access_role"><option value="manager">Blood Bank Manager</option><option value="inventory">Inventory Officer</option><option value="donor_officer">Donor Officer</option><option value="request_desk">Request Desk</option><option value="camp_coordinator">Camp Coordinator</option><option value="viewer">Analytics Viewer</option></select></label><label>Blood bank scope<select name="bank_id"><option value="">All blood banks in this tenant</option><?php foreach($banks as $b):?><option value="<?=(int)$b['id']?>"><?=e($b['name'])?></option><?php endforeach;?></select></label><button class="btn wide">Assign Blood Bank Access</button><p class="form-note">A normal customer/user account can be assigned here. It does not need the global Admin role.</p></form></aside></section>
<?php elseif($tab==='settings'&&has_permission('bloodbank.settings',$me)):?><section class="panel settings-panel"><div class="panel-head"><div><span>MODULE CONTROL</span><h3>Blood Bank settings</h3></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="settings"><div class="settings-grid"><label><input type="checkbox" name="enabled" value="1" <?=setting_bool('bloodbank_v570_enabled',true)?'checked':''?>> Enable Blood Bank module</label><label><input type="checkbox" name="guest_donors" value="1" <?=setting_bool('bloodbank_v570_guest_donors',true)?'checked':''?>> Allow guest donor registration</label><label><input type="checkbox" name="guest_requests" value="1" <?=setting_bool('bloodbank_v570_guest_requests',true)?'checked':''?>> Allow guest blood requests</label><label><input type="checkbox" name="show_inventory" value="1" <?=setting_bool('bloodbank_v570_show_inventory',true)?'checked':''?>> Show public inventory counts</label><label><input type="checkbox" name="show_public_requests" value="1" <?=setting_bool('bloodbank_v570_show_public_requests',true)?'checked':''?>> Show verified public requests</label><label><input type="checkbox" name="request_review" value="1" <?=setting_bool('bloodbank_v570_request_review',true)?'checked':''?>> Require staff verification before public request</label><label><input type="checkbox" name="slider_autoplay" value="1" <?=setting_bool('bloodbank_v570_slider_autoplay',true)?'checked':''?>> Autoplay public slider</label><label>Slider seconds<input type="number" min="3" max="20" name="slider_seconds" value="<?=setting_int('bloodbank_v570_slider_seconds',6)?>"></label><label><input type="checkbox" name="emergency_banner" value="1" <?=setting_bool('bloodbank_v570_emergency_banner',true)?'checked':''?>> Emergency request emphasis</label></div><button class="btn">Save Settings</button></form></section><?php endif;?></div><?php page_end(); ?>
